@startuml

class Song {
  + Title : string
  + Year : int
  + Length : double
  + Genre : string
}

class Artist {
  + Name : string
  + BirthDate : date
  + Website : string
}

class User {
  + UserID : int
  + Name : string
  + Address : string
}

abstract class UserType {}

class RegularUser {
  + VATNumber : string
}

class BusinessUser {}

class Album {
  + Title : string
  + Position : int
}

class Single {}

class Hit {}

RegularUser --|> UserType
BusinessUser --|> UserType

Song "1" -- "1" Artist
User "*" -- "0..*" Song
User "*" -- "0..*" Album
User "*" -- "0..*" Single
User "*" -- "0..*" Hit
Album "1" -- "*" Hit

@enduml

